<?php namespace App\Http\Requests\Admin; class RoomRequest extends \App\Http\Requests\Api\RoomRequest { protected function prepareForValidation(): void { $this->merge(["images"=>array_values(array_filter(array_map("trim",preg_split("/\r\n|\r|\n/",(string)$this->input("images_text",""))),"strlen")), "facilities"=>array_values(array_filter(array_map("trim",preg_split("/\r\n|\r|\n/",(string)$this->input("facilities_text",""))),"strlen"))]); } }
